import { live, useClaims, type ClaimStatus } from '../claims/claims';
import { crewDueTotal, useCrews } from '../crews/crews';
import { overdue } from '../overdue/overdue';
import { gradeOn, usePeople, type Person } from '../people/people';
import { personDue, personSplit, sum, trimmedSum, useRates } from '../rates/rates';
import { useCap, useFloor, useLate } from '../settings/settings';

// The sheet-wide figures shown in more than one place (the rollups, the summary and the header), worked out once
// here so every place that shows one shows the same value.

/** The statuses claims are counted by. */
export const STATUSES: readonly ClaimStatus[] = ['DRAFT', 'OPEN', 'PENDING', 'SETTLED', 'VOID', 'REVIEW'];

/** The sheet's due-total: everyone's due-total added up, skipping n/a, leaving out the single highest and lowest
 *  when three or more people have one. */
export function useSheetDueTotal(sheetId: string): string {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const cap = useCap(sheetId);
  return trimmedSum(
    (people.data ?? []).map((p) =>
      personDue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor, cap),
    ),
  );
}

/** The sheet's classic due-total: everyone's due-total added up, skipping n/a, with no trimming. */
export function useSheetDueSum(sheetId: string): string {
  const due = usePeopleDue(sheetId);
  return sum([...due.values()]);
}

/** Each person's due-total as their row shows it (two decimals, or n/a), by person id. */
export function usePeopleDue(sheetId: string): Map<number, string> {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const cap = useCap(sheetId);
  return new Map(
    (people.data ?? []).map((p) => [
      p.id,
      personDue(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor, cap),
    ]),
  );
}

/** The sheet's settled-total and open-total: everyone's added up (not trimmed). */
export function useSheetSplit(sheetId: string): { settled: string; open: string } {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const late = useLate(sheetId);
  const floor = useFloor(sheetId);
  const all = (people.data ?? []).map((p) =>
    personSplit(live(claims.data?.filter((c) => c.personId === p.id) ?? [], [p], late.today), rates.data, p, late, floor),
  );
  return { settled: sum(all.map((s) => s.settled)), open: sum(all.map((s) => s.open)) };
}

import { useCallback, useEffect, useState } from 'react';
import { useIsFetching, useMutation, useQueryClient } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { ReadNow } from '../../query/readNow';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useClaims } from '../claims/claims';
import { usePeopleDue } from '../header/totals';
import { shownName, usePeople } from '../people/people';
import { useRates } from '../rates/rates';
import { useSettings } from '../settings/settings';

/** One sheet's people, in list order, each with their names (name then aliases) and due-total as their row shows it. */
type Found = { sheetId: string; name: string; names: string[]; due: string }[];

/** Works out one sheet's people and due-totals with the same hooks as its rows, and reports them once all are read.
 *  Shows nothing. */
function SheetPeople({ sheetId, report }: { sheetId: string; report: (sheetId: string, found: Found) => void }) {
  const people = usePeople(sheetId);
  const claims = useClaims(sheetId);
  const rates = useRates(sheetId);
  const settings = useSettings(sheetId);
  const due = usePeopleDue(sheetId);
  const fetching = useIsFetching({ queryKey: ['sheet', sheetId] });
  const ready = fetching === 0 && people.isSuccess && claims.isSuccess && rates.isSuccess && settings.isSuccess;
  const found: Found | null = ready
    ? people.data.map((p) => ({ sheetId, name: shownName(p), names: [p.name, ...(p.aliases ?? [])], due: due.get(p.id) ?? 'n/a' }))
    : null;
  const key = found === null ? null : JSON.stringify(found);
  useEffect(() => {
    if (key !== null) report(sheetId, JSON.parse(key) as Found);
  }, [report, sheetId, key]);
  return null;
}

/** The tree search: every person, over this sheet and every other sheet of its tree, whose name or an alias contains the
 *  typed text (case ignored), one line each as `<sheet id> <name> (<grade>) <due-total>`: this sheet's people first in list order,
 *  then the other sheets' by sheet id. The sheets are read as they are now, afresh on each press. */
function TreeSearch({ sheetId }: { sheetId: string }) {
  const queryClient = useQueryClient();
  const [text, setText] = useState('');
  const [found, setFound] = useState<Record<string, Found>>({});
  const search = useMutation({
    mutationFn: async (typed: string) => {
      const others = await getJson<string[]>(`/api/sheets/${encodeURIComponent(sheetId)}/tree`);
      const sheets = [sheetId, ...others];
      // re-read every sheet so what another user changed is seen
      await Promise.all(sheets.map((id) => queryClient.refetchQueries({ queryKey: ['sheet', id] })));
      return { typed: typed.trim().toLowerCase(), sheets };
    },
  });
  const report = useCallback((id: string, f: Found) => setFound((all) => ({ ...all, [id]: f })), []);
  const done = search.data !== undefined && search.data.sheets.every((id) => found[id] !== undefined);
  const lines = done
    ? search.data!.sheets.flatMap((id) =>
        found[id].filter((p) => p.names.some((n) => n.toLowerCase().includes(search.data!.typed))),
      )
    : [];

  return (
    <section data-testid="tree-search">
      <h3>Search the tree</h3>
      <input
        data-testid="search-name"
        placeholder="Name or alias"
        value={text}
        onChange={(e) => {
          setText(e.target.value);
          search.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="search"
        disabled={search.isPending}
        onClick={() => {
          search.reset();
          setFound({});
          search.mutate(text);
        }}
      >

